local LuaTypeProvider = require(script.Parent.Parent.Core.DependencyInjection.LuaTypeProvider)
local LuaType = require(script.LuaType)

return function(luaTypeDefineSource: Instance): ILuaTypeProvider
	local fullNameCache: {
		[string]: LuaType,
	} = {}

	local nameCache: {
		[string]: LuaType,
	} = {}

	local function parseSource(luaTypeDefineSource: Instance): ILuaTypeProvider
		-- assert source in ModuleScript
		assert(luaTypeDefineSource:IsA("ModuleScript"), "Source must be a ModuleScript")

		-- read source code
		local configs = require(luaTypeDefineSource)

		for k, config in pairs(configs) do
			-- parse source code
			local luaType = LuaType.new(k, config)

			fullNameCache[k] = luaType

			if config.Name then
				nameCache[config.Name] = luaType
			end
		end
	end

	local module: ILuaTypeProvider = {}

	module.IsLuaTypeProvider = true

	module.GetType = function(typeName: string)
		if fullNameCache[typeName] then
			return fullNameCache[typeName]
		end
		return module.GetTypeByName(typeName)
	end

	module.GetTypeByName = function(name: string)
		if nameCache[name] then
			return nameCache[name]
		end

		return LuaType.new(name)
	end

	module.Types = fullNameCache

	parseSource(luaTypeDefineSource)

	return module
end
